TYPE = {1: 'page', 2: 'text', 3: 'h1', 4: 'h2', 5: 'h3', 6: 'h4', 12: 'bullet',
        13: 'ordered', 14: 'code', 15: 'quote', 17: 'todo', 19: 'callout',
        22: 'divider', 24: 'grid', 25: 'grid_col', 27: 'image', 31: 'table',
        32: 'table_cell', 43: 'whiteboard', 34: 'quote_container'}


def text_of(b):
    for key in ('text', 'heading1', 'heading2', 'heading3', 'heading4',
                'bullet', 'ordered', 'code', 'quote', 'todo'):
        if key in b and isinstance(b[key], dict):
            els = b[key].get('elements') or []
            s = ''
            for e in els:
                tr = e.get('text_run')
                if tr:
                    s += tr.get('content', '')
            return s
    return ''


