#!/usr/bin/env python3
"""把被转义成字面 ** 的段落，重新以 markdown 插入（让加粗生效），然后删掉坏块。

原因：docx insert 不认 <callout> 扩展标签，紧跟标签那一行被当成 HTML 块，其中的
** 被转义。标准 markdown 本身是正常的，所以把同样的文字重新 insert 一次即可。
"""
import json
import subprocess
import sys

DOC = 'Tf5EdSc4Oovlosx44wGc3fNDnbI'
TMP = '/home/mi/convwork/_fix.md'
DRY = '--apply' not in sys.argv


def sh(args):
    return subprocess.run(args, capture_output=True, text=True, timeout=300)


sh(['bash', '-c',
    'feishu docx blocks %s > /home/mi/convwork/fs_blocks.json 2>&1' % DOC])

d = json.load(open('/home/mi/convwork/fs_blocks.json'))
by_id = {}


def collect(o):
    if isinstance(o, dict):
        if 'block_id' in o:
            by_id[o['block_id']] = o
        for v in o.values():
            collect(v)
    elif isinstance(o, list):
        for v in o:
            collect(v)


collect(d)

targets = []
for bid, b in by_id.items():
    if b.get('block_type') != 2:
        continue
    t = b.get('text') or {}
    els = t.get('elements') or []
    s = ''
    for e in els:
        tr = e.get('text_run')
        if tr:
            s += tr.get('content', '')
    if '**' in s:
        targets.append((bid, s))

print('找到含字面 ** 的文本块:', len(targets))
for bid, s in targets:
    print('  ', bid, s[:60])

if DRY:
    print('\n(dry-run，加 --apply 才执行)')
    sys.exit(0)

log = open('/home/mi/convwork/fix_stars.log', 'w')
ok_n = 0
for bid, s in targets:
    with open(TMP, 'w') as f:
        f.write(s + '\n')
    p = sh(['feishu', 'docx', 'insert', DOC, bid, '-f', TMP])
    ins_ok = '"success": true' in p.stdout
    del_ok = False
    if ins_ok:
        q = sh(['feishu', 'docx', 'delete-block', DOC, bid])
        del_ok = '"success": true' in q.stdout
    line = '%s ins=%s del=%s  %s' % (bid, ins_ok, del_ok, s[:45])
    print(line)
    log.write(line + '\n')
    log.flush()
    if ins_ok and del_ok:
        ok_n += 1

log.write('\nfixed %d / %d\n' % (ok_n, len(targets)))
log.close()
print('fixed %d / %d' % (ok_n, len(targets)))
